-- data/actor_profiles.lua: one ActorProfile per actor archetype, merging:
--   repo actor_ai.lua `profiles` (package ids, action kind/code, movement/projectile flags) [repo; values match ROM below]
--   sprite_type      : actor +0x0E (SpriteType; 3/5/11/14 names from repo) [C values / H names]
--   entry_sound      : word table 0xB05E indexed by +0x0E, read by 0xB330 (16 entries, below) [C]
--   weapon           : ItemId -> data/weapons.lua record (corp guard = Max-Power, repo + ROM item 6) [C]
--   reinforcement    : building spawn profile +0x10 used by the alarm spawner 0x1E04A (doc 20a §10) - per-building,
--                      so it lives on the building/run record, not here [C].
-- Generated by an inline script from the repo + rom.bin; regenerate rather than hand-edit.
local E = require("enums")
local SpriteType, ItemId = E.SpriteType, E.ItemId

local ENTRY_SOUND_BY_SPRITE = { [0] = 0x40, [1] = 0x40, [2] = 0x40, [3] = 0x2E, [4] = 0x2F, [5] = 0x2E, [6] = 0x58, [7] = 0x2E, [8] = 0x2E, [9] = 0x2E, [10] = 0x58, [11] = 0x2F, [12] = 0x56, [13] = 0x5A, [14] = 0x5A, [15] = 0x5A }   -- 0xB05E [C]

---@class ActorProfile
local ActorProfile = {}
ActorProfile.__index = ActorProfile
setmetatable(ActorProfile, { __call = function(_, t) return setmetatable(t, ActorProfile) end })
function ActorProfile:weapon_record() return self.weapon and require("data.weapons").get(self.weapon) or nil end
function ActorProfile:is_armed() return self.weapon ~= nil end

local M = { ActorProfile = ActorProfile, ENTRY_SOUND_BY_SPRITE = ENTRY_SOUND_BY_SPRITE, by_id = {
    ["corp_guard_k05_item06"] = ActorProfile{ id = "corp_guard_k05_item06", package_id = "corp_security.max_power_heavy_pistol", sprite_type = SpriteType.CORP_GUARD, action_kind = "item", action_code = ItemId.MAX_POWER, weapon = ItemId.MAX_POWER, entry_sound = 0x2E, controls_movement = false, projectile = false, dynamic_encounter_only = false },
    ["pedestrian_k0b_none00"] = ActorProfile{ id = "pedestrian_k0b_none00", package_id = "pedestrian.no_active_action", sprite_type = SpriteType.PEDESTRIAN, action_kind = "none", action_code = ItemId.NONE, weapon = nil, entry_sound = 0x2F, controls_movement = false, projectile = false, dynamic_encounter_only = false },
    ["field_runner_k03_none00"] = ActorProfile{ id = "field_runner_k03_none00", package_id = "runner.field_controlled", sprite_type = SpriteType.FIELD_RUNNER, action_kind = "none", action_code = ItemId.NONE, weapon = nil, entry_sound = 0x2E, controls_movement = true, projectile = false, dynamic_encounter_only = false },
    ["hell_hound_k0c_none00"] = ActorProfile{ id = "hell_hound_k0c_none00", package_id = "creature.hell_hound.source_target_motion", sprite_type = SpriteType.HELL_HOUND, action_kind = "none", action_code = ItemId.NONE, weapon = nil, entry_sound = 0x56, controls_movement = true, projectile = false, dynamic_encounter_only = true },
    ["gargoyle_k0d_none00"] = ActorProfile{ id = "gargoyle_k0d_none00", package_id = "creature.gargoyle.source_target_motion", sprite_type = SpriteType.GARGOYLE, action_kind = "none", action_code = ItemId.NONE, weapon = nil, entry_sound = 0x5A, controls_movement = true, projectile = false, dynamic_encounter_only = true },
    ["wendigo_k0e_none00"] = ActorProfile{ id = "wendigo_k0e_none00", package_id = "creature.wendigo.source_target_motion", sprite_type = SpriteType.WENDIGO, action_kind = "none", action_code = ItemId.NONE, weapon = nil, entry_sound = 0x5A, controls_movement = true, projectile = false, dynamic_encounter_only = true },
    ["weapon_projectile"] = ActorProfile{ id = "weapon_projectile", package_id = "combat.weapon_projectile", sprite_type = nil, action_kind = "none", action_code = ItemId.NONE, weapon = nil, entry_sound = nil, controls_movement = false, projectile = true, dynamic_encounter_only = false },
} }
-- Dynamic encounter profiles are synthesised from "<name>_kXX_<kind>YY" ids (repo dynamic_encounter_profile).
function M.dynamic(sprite_type, action_kind, action_code)
    return ActorProfile{ id = string.format("dyn_k%02x_%s%02x", sprite_type, action_kind, action_code),
        sprite_type = sprite_type, action_kind = action_kind, action_code = action_code,
        weapon = action_kind == "item" and action_code or nil, entry_sound = ENTRY_SOUND_BY_SPRITE[sprite_type],
        controls_movement = true, projectile = false, dynamic_encounter_only = true }
end
return M
